INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dfb8508a-8d0b-5c72-9731-dbed28ae0df1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', $$What is the key difference between RADIUS and TACACS+?$$::text, $$[{"id": "A", "text": "IPv4 uses 32-bit addresses; IPv6 uses 128-bit addresses and has no broadcasts.", "is_correct": false}, {"id": "B", "text": "2.4 GHz has longer range and more interference; 5 GHz has shorter range and more channels.", "is_correct": false}, {"id": "C", "text": "RADIUS combines auth/authz and uses UDP; TACACS+ separates AAA and uses TCP.", "is_correct": true}, {"id": "D", "text": "WPA2-Personal uses a pre-shared key; WPA2-Enterprise uses 802.1X/RADIUS per-user authentication.", "is_correct": false}]$$::jsonb, $$RADIUS combines auth/authz and uses UDP; TACACS+ separates AAA and uses TCP.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$5.0 Security Fundamentals$$::text, 15.0, '69db8847269f091c', true) ON CONFLICT (id) DO NOTHING;
