INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8447f40-167f-5af0-8f8c-00a65126ad39', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', $$What is the key difference between Router and Switch?$$::text, $$[{"id": "A", "text": "IDS detects and alerts; IPS detects and actively blocks.", "is_correct": false}, {"id": "B", "text": "A hub repeats signals to all ports; a switch forwards frames only to the destination port.", "is_correct": false}, {"id": "C", "text": "A router operates at Layer 3 using IP addresses; a switch operates at Layer 2 using MAC addresses.", "is_correct": true}, {"id": "D", "text": "Standard ACLs filter by source IP; extended ACLs filter by source/destination IP, port, and protocol.", "is_correct": false}]$$::jsonb, $$A router operates at Layer 3 using IP addresses; a switch operates at Layer 2 using MAC addresses.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$1.0 Network Fundamentals$$::text, 20.0, '2a380a85bb547a80', true) ON CONFLICT (id) DO NOTHING;
