INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e07bb4a-e95b-5128-ab84-a9bb20c105ab', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$A Cisco switch has DTP enabled on a port. The neighboring device is configured as 'switchport mode trunk'. What is the expected result?$$::text, $$[{"id": "A", "text": "The server returns HTTP 201 Created.", "is_correct": false}, {"id": "B", "text": "The local port negotiates to trunking if in dynamic desirable or auto mode.", "is_correct": true}, {"id": "C", "text": "The switch dynamically learns and saves the MAC as a secure address.", "is_correct": false}, {"id": "D", "text": "Untagged traffic may leak between the two native VLANs.", "is_correct": false}]$$::jsonb, $$Given A Cisco switch has DTP enabled on a port. and The neighboring device is configured as 'switchport mode trunk'., the result is: The local port negotiates to trunking if in dynamic desirable or auto mode.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$2.0 Network Access$$::text, 20.0, '2f7f02de09ff1c01', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('891fd365-1d25-553d-900e-77bfbff3ca6b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$A switch trunk is configured with allowed vlan 10,20. A frame tagged with VLAN 30 arrives on the trunk. What is the expected result?$$::text, $$[{"id": "A", "text": "The switch associates the frame with VLAN 30.", "is_correct": false}, {"id": "B", "text": "The switch drops the frame because VLAN 30 is not allowed on the trunk.", "is_correct": true}, {"id": "C", "text": "The router performs equal-cost load balancing across both paths.", "is_correct": false}, {"id": "D", "text": "The client may not be able to connect unless backward compatibility is enabled.", "is_correct": false}]$$::jsonb, $$Given A switch trunk is configured with allowed vlan 10,20. and A frame tagged with VLAN 30 arrives on the trunk., the result is: The switch drops the frame because VLAN 30 is not allowed on the trunk.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$2.0 Network Access$$::text, 20.0, '586247108f46eecf', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('da3a5384-183b-5d9b-9882-f98fa2204a54', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$An engineer configures a floating static route with AD 200. The same prefix is learned via OSPF with AD 110. What is the expected result?$$::text, $$[{"id": "A", "text": "The router uses both paths for traffic to that destination.", "is_correct": false}, {"id": "B", "text": "Traffic to the gateway is redirected through the attacker (ARP spoofing/MITM).", "is_correct": false}, {"id": "C", "text": "The OSPF route is preferred; the static route appears only if OSPF route disappears.", "is_correct": true}, {"id": "D", "text": "The switch forwards the frame only out the destination port.", "is_correct": false}]$$::jsonb, $$Given An engineer configures a floating static route with AD 200. and The same prefix is learned via OSPF with AD 110., the result is: The OSPF route is preferred; the static route appears only if OSPF route disappears.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$3.0 IP Connectivity$$::text, 25.0, '2e67ec8a8fcbf50d', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95ccdfd6-f39d-5392-b78d-9589f78511f8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$A switch receives a frame with a known destination MAC on a different port. The source MAC is already in the table. What is the expected result?$$::text, $$[{"id": "A", "text": "The switch forwards the frame only out the destination port.", "is_correct": true}, {"id": "B", "text": "The client maintains connectivity with minimal interruption.", "is_correct": false}, {"id": "C", "text": "The switch may flood traffic out all ports, enabling sniffing.", "is_correct": false}, {"id": "D", "text": "New authentications fail; previously authenticated sessions may remain depending on configuration.", "is_correct": false}]$$::jsonb, $$Given A switch receives a frame with a known destination MAC on a different port. and The source MAC is already in the table., the result is: The switch forwards the frame only out the destination port.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$2.0 Network Access$$::text, 20.0, '75aa1a309baabc58', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d3df912-effc-5638-aa16-bf7483802d05', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$A switch port has port-security configured with maximum 2 MAC addresses. A third MAC address attempts to send traffic. What is the expected result?$$::text, $$[{"id": "A", "text": "The router acts as an NTP server with stratum 3.", "is_correct": false}, {"id": "B", "text": "The server returns HTTP 204 No Content on success.", "is_correct": false}, {"id": "C", "text": "The port triggers a security violation and may shut down or restrict.", "is_correct": true}, {"id": "D", "text": "The server returns HTTP 201 Created.", "is_correct": false}]$$::jsonb, $$Given A switch port has port-security configured with maximum 2 MAC addresses. and A third MAC address attempts to send traffic., the result is: The port triggers a security violation and may shut down or restrict.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$5.0 Security Fundamentals$$::text, 15.0, '0de94f1f49bf29e9', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9068862a-9865-5d33-924a-588f16fa859f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$An API client sends a POST request to a REST endpoint. The request body is valid JSON and the resource is created. What is the expected result?$$::text, $$[{"id": "A", "text": "The server returns HTTP 201 Created.", "is_correct": true}, {"id": "B", "text": "The port remains in unauthorized state and blocks data traffic.", "is_correct": false}, {"id": "C", "text": "The switch forwards the frame only out the destination port.", "is_correct": false}, {"id": "D", "text": "The EIGRP route is installed because it has the lower administrative distance.", "is_correct": false}]$$::jsonb, $$Given An API client sends a POST request to a REST endpoint. and The request body is valid JSON and the resource is created., the result is: The server returns HTTP 201 Created.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$6.0 Automation and Programmability$$::text, 10.0, '6350774b01eaf5b3', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

