INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15fbe3c9-71d0-571d-841d-34f9fff63811', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$A BGP router receives two paths for the same prefix. One path has a shorter AS_PATH. What is the expected result?$$::text, $$[{"id": "A", "text": "NAT translation does not occur because the outside interface is not marked.", "is_correct": false}, {"id": "B", "text": "The server returns HTTP 201 Created.", "is_correct": false}, {"id": "C", "text": "If all higher-priority attributes are equal, the path with the shorter AS_PATH is selected.", "is_correct": true}, {"id": "D", "text": "The host may not communicate with hosts outside its /27 unless the router has correct routes.", "is_correct": false}]$$::jsonb, $$Given A BGP router receives two paths for the same prefix. and One path has a shorter AS_PATH., the result is: If all higher-priority attributes are equal, the path with the shorter AS_PATH is selected.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$3.0 IP Connectivity$$::text, 25.0, '5e8e649ec25fd972', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

