INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('584dee60-5608-5264-9105-bb8a4215942b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$An attacker performs a MAC flooding attack. The switch MAC address table fills with bogus entries. What is the expected result?$$::text, $$[{"id": "A", "text": "The switch floods the frame out all ports in the same VLAN except the ingress port.", "is_correct": false}, {"id": "B", "text": "The switch may flood traffic out all ports, enabling sniffing.", "is_correct": true}, {"id": "C", "text": "The switch drops the frame because VLAN 30 is not allowed on the trunk.", "is_correct": false}, {"id": "D", "text": "The router uses both paths for traffic to that destination.", "is_correct": false}]$$::jsonb, $$Given An attacker performs a MAC flooding attack. and The switch MAC address table fills with bogus entries., the result is: The switch may flood traffic out all ports, enabling sniffing.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$5.0 Security Fundamentals$$::text, 15.0, 'ce8c9d5bfd34f07c', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef82009f-4a5b-58ab-af7a-eb83657390a1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$A Cisco router uses CBWFQ. One class exceeds its configured bandwidth. What is the expected result?$$::text, $$[{"id": "A", "text": "Excess traffic is queued and may be dropped if the queue overflows.", "is_correct": true}, {"id": "B", "text": "The host uses APIPA and cannot communicate outside the local segment.", "is_correct": false}, {"id": "C", "text": "The route with MED 50 is preferred because lower MED is preferred.", "is_correct": false}, {"id": "D", "text": "The second interface may display an IP overlap error depending on IOS version.", "is_correct": false}]$$::jsonb, $$Given A Cisco router uses CBWFQ. and One class exceeds its configured bandwidth., the result is: Excess traffic is queued and may be dropped if the queue overflows.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$4.0 IP Services$$::text, 10.0, 'fcad2b6c5ae318da', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc343a5a-48a5-5bbb-8f74-41e86a86f9a5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$A switch receives a unicast frame with an unknown destination MAC. The destination MAC is not in the MAC address table. What is the expected result?$$::text, $$[{"id": "A", "text": "If all higher-priority attributes are equal, the path with the shorter AS_PATH is selected.", "is_correct": false}, {"id": "B", "text": "The client resolves the name to an IPv4 address.", "is_correct": false}, {"id": "C", "text": "The switch floods the frame out all ports in the same VLAN except the ingress port.", "is_correct": true}, {"id": "D", "text": "The switch drops the frame because VLAN 30 is not allowed on the trunk.", "is_correct": false}]$$::jsonb, $$Given A switch receives a unicast frame with an unknown destination MAC. and The destination MAC is not in the MAC address table., the result is: The switch floods the frame out all ports in the same VLAN except the ingress port.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$2.0 Network Access$$::text, 20.0, '31d4ca7d7f916ae5', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0987b550-d246-50fd-a37c-dc147e036a84', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$A switch port is configured with BPDU Guard and PortFast. The port receives a BPDU from an accidentally connected switch. What is the expected result?$$::text, $$[{"id": "A", "text": "The EIGRP route is installed because it has the lower administrative distance.", "is_correct": false}, {"id": "B", "text": "The switch associates the frame with VLAN 30.", "is_correct": false}, {"id": "C", "text": "The router forwards the Discover as a unicast to the DHCP server.", "is_correct": false}, {"id": "D", "text": "The port is placed into err-disabled state.", "is_correct": true}]$$::jsonb, $$Given A switch port is configured with BPDU Guard and PortFast. and The port receives a BPDU from an accidentally connected switch., the result is: The port is placed into err-disabled state.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$2.0 Network Access$$::text, 20.0, 'f3da835d08698462', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4ab90ea3-a086-5110-8c04-0d074cbc9529', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$A switch port is set to 'switchport mode access' and assigned to VLAN 30. A frame without a VLAN tag arrives on the port. What is the expected result?$$::text, $$[{"id": "A", "text": "The client resolves the name to an IPv4 address.", "is_correct": false}, {"id": "B", "text": "Telnet sessions are blocked by the ACL.", "is_correct": false}, {"id": "C", "text": "The switch associates the frame with VLAN 30.", "is_correct": true}, {"id": "D", "text": "Excess traffic is queued and may be dropped if the queue overflows.", "is_correct": false}]$$::jsonb, $$Given A switch port is set to 'switchport mode access' and assigned to VLAN 30. and A frame without a VLAN tag arrives on the port., the result is: The switch associates the frame with VLAN 30.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$2.0 Network Access$$::text, 20.0, 'c0972c4d9b6b6612', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('72d069cf-46d2-5bc0-a572-cfcbe4de024d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$A wireless client is associated to an AP on channel 1. A neighboring AP is also on channel 1 with overlapping coverage. What is the expected result?$$::text, $$[{"id": "A", "text": "The port remains in unauthorized state and blocks data traffic.", "is_correct": false}, {"id": "B", "text": "Co-channel interference may degrade performance.", "is_correct": true}, {"id": "C", "text": "The server returns HTTP 201 Created.", "is_correct": false}, {"id": "D", "text": "Traffic from the server back to the user is blocked because standard ACLs do not filter return traffic based on destination.", "is_correct": false}]$$::jsonb, $$Given A wireless client is associated to an AP on channel 1. and A neighboring AP is also on channel 1 with overlapping coverage., the result is: Co-channel interference may degrade performance.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$2.0 Network Access$$::text, 20.0, '4c346dcb0b4bfd3d', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('10b7d67e-4146-533f-8cfe-f6d015043b72', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$An engineer runs 'show ip route' and sees two equal-cost paths to the same destination. The routing protocol supports equal-cost load balancing. What is the expected result?$$::text, $$[{"id": "A", "text": "Excess traffic is queued and may be dropped if the queue overflows.", "is_correct": false}, {"id": "B", "text": "The client cannot associate and remains unauthenticated.", "is_correct": false}, {"id": "C", "text": "The router forwards the Discover as a unicast to the DHCP server.", "is_correct": false}, {"id": "D", "text": "The router uses both paths for traffic to that destination.", "is_correct": true}]$$::jsonb, $$Given An engineer runs 'show ip route' and sees two equal-cost paths to the same destination. and The routing protocol supports equal-cost load balancing., the result is: The router uses both paths for traffic to that destination.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$3.0 IP Connectivity$$::text, 25.0, 'd67e6c288bd1c6e9', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('acfb5f65-4ad5-598b-b289-8e836cfecb25', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$A switch has spanning-tree PortFast enabled on a trunk port. The trunk receives a BPDU. What is the expected result?$$::text, $$[{"id": "A", "text": "The switch floods the frame out all ports in the same VLAN except Gi0/1.", "is_correct": false}, {"id": "B", "text": "BPDU Guard may place the port into err-disabled state.", "is_correct": true}, {"id": "C", "text": "The router translates 192.168.1.10 to a public address before forwarding.", "is_correct": false}, {"id": "D", "text": "The host does not receive an IP address because broadcasts are not forwarded across subnets.", "is_correct": false}]$$::jsonb, $$Given A switch has spanning-tree PortFast enabled on a trunk port. and The trunk receives a BPDU., the result is: BPDU Guard may place the port into err-disabled state.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$2.0 Network Access$$::text, 20.0, '978c5154135e62bb', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e3dd6e21-2eab-509d-afaa-f70072964871', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$A switch port is configured with 'switchport port-security mac-address sticky'. A new host connects to the port. What is the expected result?$$::text, $$[{"id": "A", "text": "The switch dynamically learns and saves the MAC as a secure address.", "is_correct": true}, {"id": "B", "text": "The router performs equal-cost load balancing across both paths.", "is_correct": false}, {"id": "C", "text": "Traffic to the gateway is redirected through the attacker (ARP spoofing/MITM).", "is_correct": false}, {"id": "D", "text": "NAT translation does not occur because the outside interface is not marked.", "is_correct": false}]$$::jsonb, $$Given A switch port is configured with 'switchport port-security mac-address sticky'. and A new host connects to the port., the result is: The switch dynamically learns and saves the MAC as a secure address.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$5.0 Security Fundamentals$$::text, 15.0, '412b0069c5d8f567', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('23457069-1566-5f53-88ea-54ea34cdc3a4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$An Ansible playbook is executed against a group of switches. The playbook uses the 'ios_config' module with a template. What is the expected result?$$::text, $$[{"id": "A", "text": "The second interface may display an IP overlap error depending on IOS version.", "is_correct": false}, {"id": "B", "text": "The router performs equal-cost load balancing across both paths.", "is_correct": false}, {"id": "C", "text": "The response status code is 200 OK.", "is_correct": false}, {"id": "D", "text": "Ansible pushes the rendered configuration to each switch.", "is_correct": true}]$$::jsonb, $$Given An Ansible playbook is executed against a group of switches. and The playbook uses the 'ios_config' module with a template., the result is: Ansible pushes the rendered configuration to each switch.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$6.0 Automation and Programmability$$::text, 10.0, 'f6ded65f5b1b8532', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4feed874-163b-53b9-a50d-4591e5f319a8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$A router has a static route pointing to a next-hop that is currently down. No other route to the destination exists. What is the expected result?$$::text, $$[{"id": "A", "text": "The static route disappears from the routing table.", "is_correct": true}, {"id": "B", "text": "Excess traffic is queued and may be dropped if the queue overflows.", "is_correct": false}, {"id": "C", "text": "The switch forwards the frame only out the destination port.", "is_correct": false}, {"id": "D", "text": "If all higher-priority attributes are equal, the path with the shorter AS_PATH is selected.", "is_correct": false}]$$::jsonb, $$Given A router has a static route pointing to a next-hop that is currently down. and No other route to the destination exists., the result is: The static route disappears from the routing table.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$3.0 IP Connectivity$$::text, 25.0, '6f500b9c552c5fef', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('786e6da2-ec75-5ba0-b501-49d658d6876b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$A DNS client queries for www.example.com. The authoritative server responds with an A record. What is the expected result?$$::text, $$[{"id": "A", "text": "The client resolves the name to an IPv4 address.", "is_correct": true}, {"id": "B", "text": "The response status code is 200 OK.", "is_correct": false}, {"id": "C", "text": "The server returns HTTP 204 No Content on success.", "is_correct": false}, {"id": "D", "text": "Traffic to the gateway is redirected through the attacker (ARP spoofing/MITM).", "is_correct": false}]$$::jsonb, $$Given A DNS client queries for www.example.com. and The authoritative server responds with an A record., the result is: The client resolves the name to an IPv4 address.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$4.0 IP Services$$::text, 10.0, '3b4c0d212f04d919', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dcf2aad3-9293-5622-83cd-973f603d39e1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$A BGP router receives a route with MED 50 from one peer and MED 100 from another. All higher-priority attributes are equal. What is the expected result?$$::text, $$[{"id": "A", "text": "The server returns HTTP 201 Created.", "is_correct": false}, {"id": "B", "text": "OSPF will not form adjacencies until the interface is no shutdown.", "is_correct": false}, {"id": "C", "text": "The route with MED 50 is preferred because lower MED is preferred.", "is_correct": true}, {"id": "D", "text": "The response status code is 200 OK.", "is_correct": false}]$$::jsonb, $$Given A BGP router receives a route with MED 50 from one peer and MED 100 from another. and All higher-priority attributes are equal., the result is: The route with MED 50 is preferred because lower MED is preferred.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$3.0 IP Connectivity$$::text, 25.0, 'f4d85ba3581a5e40', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7d3a4169-ea12-536d-932b-adf0c02f9600', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$A router interface is configured with ip nat inside but not ip nat outside. Traffic arrives from the inside interface destined to the Internet. What is the expected result?$$::text, $$[{"id": "A", "text": "Untagged traffic may leak between the two native VLANs.", "is_correct": false}, {"id": "B", "text": "The host may not communicate with hosts outside its /27 unless the router has correct routes.", "is_correct": false}, {"id": "C", "text": "The switch dynamically learns and saves the MAC as a secure address.", "is_correct": false}, {"id": "D", "text": "NAT translation does not occur because the outside interface is not marked.", "is_correct": true}]$$::jsonb, $$Given A router interface is configured with ip nat inside but not ip nat outside. and Traffic arrives from the inside interface destined to the Internet., the result is: NAT translation does not occur because the outside interface is not marked.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$4.0 IP Services$$::text, 10.0, 'c013d08da9269624', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff1006ac-ac79-5bfe-b5e0-8b5a7a4653c4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$An OSPF router has two paths to 10.0.0.0/24. One path is intra-area with cost 20; the other is inter-area with cost 15. What is the expected result?$$::text, $$[{"id": "A", "text": "The port remains in unauthorized state and blocks data traffic.", "is_correct": false}, {"id": "B", "text": "The router chooses the intra-area path because intra-area is preferred over inter-area regardless of cost.", "is_correct": true}, {"id": "C", "text": "The client may not be able to connect unless backward compatibility is enabled.", "is_correct": false}, {"id": "D", "text": "The port triggers a security violation and may shut down or restrict.", "is_correct": false}]$$::jsonb, $$Given An OSPF router has two paths to 10.0.0.0/24. and One path is intra-area with cost 20; the other is inter-area with cost 15., the result is: The router chooses the intra-area path because intra-area is preferred over inter-area regardless of cost.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$3.0 IP Connectivity$$::text, 25.0, '2ce6b56e1372debf', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c95640b2-e666-57c6-827a-118d645849b6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$A REST API client sends GET /api/devices. The server returns a list of devices in JSON. What is the expected result?$$::text, $$[{"id": "A", "text": "If all higher-priority attributes are equal, the path with the shorter AS_PATH is selected.", "is_correct": false}, {"id": "B", "text": "Traffic from the server back to the user is blocked because standard ACLs do not filter return traffic based on destination.", "is_correct": false}, {"id": "C", "text": "The response status code is 200 OK.", "is_correct": true}, {"id": "D", "text": "The router performs equal-cost load balancing across both paths.", "is_correct": false}]$$::jsonb, $$Given A REST API client sends GET /api/devices. and The server returns a list of devices in JSON., the result is: The response status code is 200 OK.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$6.0 Automation and Programmability$$::text, 10.0, '8f10a817f62fb917', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

