INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a273657-850f-5802-be33-593e517cb956', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$A wireless network uses WPA3. A client supports only WPA2. What is the expected result?$$::text, $$[{"id": "A", "text": "The router chooses the intra-area path because intra-area is preferred over inter-area regardless of cost.", "is_correct": false}, {"id": "B", "text": "HTTP sessions work, but other TCP applications are blocked.", "is_correct": false}, {"id": "C", "text": "The router acts as an NTP server with stratum 3.", "is_correct": false}, {"id": "D", "text": "The client may not be able to connect unless backward compatibility is enabled.", "is_correct": true}]$$::jsonb, $$Given A wireless network uses WPA3. and A client supports only WPA2., the result is: The client may not be able to connect unless backward compatibility is enabled.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$5.0 Security Fundamentals$$::text, 15.0, '5dc8338e6eb9b5ab', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9417454-93ac-5f7a-a0eb-22bf294355c6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$An OSPF DR fails on a broadcast segment. The BDR is functioning. What is the expected result?$$::text, $$[{"id": "A", "text": "The port triggers a security violation and may shut down or restrict.", "is_correct": false}, {"id": "B", "text": "The BDR takes over as the new DR and a new BDR is elected.", "is_correct": true}, {"id": "C", "text": "The host may not communicate with hosts outside its /27 unless the router has correct routes.", "is_correct": false}, {"id": "D", "text": "The switch dynamically learns and saves the MAC as a secure address.", "is_correct": false}]$$::jsonb, $$Given An OSPF DR fails on a broadcast segment. and The BDR is functioning., the result is: The BDR takes over as the new DR and a new BDR is elected.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$3.0 IP Connectivity$$::text, 25.0, '404f0b9969de59be', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a87e790d-a16b-5368-bd5c-6d7d194677f0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$A router receives a packet destined to 224.0.0.5. The router is running OSPF on the ingress interface. What is the expected result?$$::text, $$[{"id": "A", "text": "The router chooses the intra-area path because intra-area is preferred over inter-area regardless of cost.", "is_correct": false}, {"id": "B", "text": "The client may not be able to connect unless backward compatibility is enabled.", "is_correct": false}, {"id": "C", "text": "The router uses both paths for traffic to that destination.", "is_correct": false}, {"id": "D", "text": "The router processes the packet as an OSPF multicast.", "is_correct": true}]$$::jsonb, $$Given A router receives a packet destined to 224.0.0.5. and The router is running OSPF on the ingress interface., the result is: The router processes the packet as an OSPF multicast.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$3.0 IP Connectivity$$::text, 25.0, '02423fa5c60442a6', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('153164c8-1814-59c9-a5a5-5f3b0a2bd319', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$A switch has 'spanning-tree portfast default' enabled. A looped cable accidentally connects two access ports on the same switch. What is the expected result?$$::text, $$[{"id": "A", "text": "The second interface may display an IP overlap error depending on IOS version.", "is_correct": false}, {"id": "B", "text": "A temporary Layer 2 loop may form until STP converges; BPDU Guard can prevent it.", "is_correct": true}, {"id": "C", "text": "The router processes the packet as an OSPF multicast.", "is_correct": false}, {"id": "D", "text": "Untagged traffic may leak between the two native VLANs.", "is_correct": false}]$$::jsonb, $$Given A switch has 'spanning-tree portfast default' enabled. and A looped cable accidentally connects two access ports on the same switch., the result is: A temporary Layer 2 loop may form until STP converges; BPDU Guard can prevent it.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$2.0 Network Access$$::text, 20.0, '97939ef3d02cf496', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('603859bb-fbf4-5f44-b78c-1c37bd76be94', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$An EIGRP router loses its successor for a route but has a feasible successor. The feasible successor satisfies the feasibility condition. What is the expected result?$$::text, $$[{"id": "A", "text": "DUAL immediately promotes the feasible successor to successor without active querying.", "is_correct": true}, {"id": "B", "text": "The router translates 192.168.1.10 to a public address before forwarding.", "is_correct": false}, {"id": "C", "text": "The server returns HTTP 204 No Content on success.", "is_correct": false}, {"id": "D", "text": "Untagged traffic may leak between the two native VLANs.", "is_correct": false}]$$::jsonb, $$Given An EIGRP router loses its successor for a route but has a feasible successor. and The feasible successor satisfies the feasibility condition., the result is: DUAL immediately promotes the feasible successor to successor without active querying.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$3.0 IP Connectivity$$::text, 25.0, '528d251e7deff16c', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('06d8b76c-e553-584e-a9c8-fe291fffc7fe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$A wireless controller uses WPA2-Enterprise. A client fails 802.1X authentication. What is the expected result?$$::text, $$[{"id": "A", "text": "BPDU Guard may place the port into err-disabled state.", "is_correct": false}, {"id": "B", "text": "The router performs equal-cost load balancing across both paths.", "is_correct": false}, {"id": "C", "text": "Telnet sessions are blocked by the ACL.", "is_correct": false}, {"id": "D", "text": "The client cannot associate and remains unauthenticated.", "is_correct": true}]$$::jsonb, $$Given A wireless controller uses WPA2-Enterprise. and A client fails 802.1X authentication., the result is: The client cannot associate and remains unauthenticated.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$5.0 Security Fundamentals$$::text, 15.0, '4ebb45b63bbbd27e', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('263bec5e-6a79-520f-802e-548855f1daaa', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$A host is configured with IP 169.254.1.10/16. No DHCP server is reachable. What is the expected result?$$::text, $$[{"id": "A", "text": "The host uses APIPA and cannot communicate outside the local segment.", "is_correct": true}, {"id": "B", "text": "BPDU Guard may place the port into err-disabled state.", "is_correct": false}, {"id": "C", "text": "The router uses both paths for traffic to that destination.", "is_correct": false}, {"id": "D", "text": "The switch floods the frame out all ports in the same VLAN except Gi0/1.", "is_correct": false}]$$::jsonb, $$Given A host is configured with IP 169.254.1.10/16. and No DHCP server is reachable., the result is: The host uses APIPA and cannot communicate outside the local segment.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$4.0 IP Services$$::text, 10.0, 'b855f6c97908f4df', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('daa8306d-6124-5b35-ae09-ddd199be89b7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$A router has ip helper-address configured on an interface. A host on that interface sends a DHCP Discover. What is the expected result?$$::text, $$[{"id": "A", "text": "The port triggers a security violation and may shut down or restrict.", "is_correct": false}, {"id": "B", "text": "The router forwards the Discover as a unicast to the DHCP server.", "is_correct": true}, {"id": "C", "text": "Traffic from the server back to the user is blocked because standard ACLs do not filter return traffic based on destination.", "is_correct": false}, {"id": "D", "text": "The OSPF route is preferred; the static route appears only if OSPF route disappears.", "is_correct": false}]$$::jsonb, $$Given A router has ip helper-address configured on an interface. and A host on that interface sends a DHCP Discover., the result is: The router forwards the Discover as a unicast to the DHCP server.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$4.0 IP Services$$::text, 10.0, 'd28b7a8c8c8c0217', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04bc0f61-30a3-5ad9-8a29-d151c04813fd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$A wireless client roams from AP1 to AP2 in the same WLAN. The WLC manages both APs with fast roaming enabled. What is the expected result?$$::text, $$[{"id": "A", "text": "The client maintains connectivity with minimal interruption.", "is_correct": true}, {"id": "B", "text": "The port is placed into err-disabled state.", "is_correct": false}, {"id": "C", "text": "Traffic from the server back to the user is blocked because standard ACLs do not filter return traffic based on destination.", "is_correct": false}, {"id": "D", "text": "The client may not be able to connect unless backward compatibility is enabled.", "is_correct": false}]$$::jsonb, $$Given A wireless client roams from AP1 to AP2 in the same WLAN. and The WLC manages both APs with fast roaming enabled., the result is: The client maintains connectivity with minimal interruption.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$2.0 Network Access$$::text, 20.0, 'a24d032d29afb71a', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f733b21-3351-5b26-ae06-278e4f4197eb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$An attacker sends forged ARP replies mapping the default gateway IP to the attacker's MAC. Hosts update their ARP caches with the attacker's MAC. What is the expected result?$$::text, $$[{"id": "A", "text": "HTTP sessions work, but other TCP applications are blocked.", "is_correct": false}, {"id": "B", "text": "Traffic to the gateway is redirected through the attacker (ARP spoofing/MITM).", "is_correct": true}, {"id": "C", "text": "OSPF will not form adjacencies until the interface is no shutdown.", "is_correct": false}, {"id": "D", "text": "The port triggers a security violation and may shut down or restrict.", "is_correct": false}]$$::jsonb, $$Given An attacker sends forged ARP replies mapping the default gateway IP to the attacker's MAC. and Hosts update their ARP caches with the attacker's MAC., the result is: Traffic to the gateway is redirected through the attacker (ARP spoofing/MITM).$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$5.0 Security Fundamentals$$::text, 15.0, 'ab394a0bcddcb234', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af531eaa-1bc4-553b-88dc-c00352571770', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$A network administrator applies an extended ACL inbound on a router interface. The ACL permits HTTP but denies all other TCP traffic. What is the expected result?$$::text, $$[{"id": "A", "text": "Telnet sessions are blocked by the ACL.", "is_correct": false}, {"id": "B", "text": "HTTP sessions work, but other TCP applications are blocked.", "is_correct": true}, {"id": "C", "text": "The client resolves the name to an IPv4 address.", "is_correct": false}, {"id": "D", "text": "Untagged traffic may leak between the two native VLANs.", "is_correct": false}]$$::jsonb, $$Given A network administrator applies an extended ACL inbound on a router interface. and The ACL permits HTTP but denies all other TCP traffic., the result is: HTTP sessions work, but other TCP applications are blocked.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$5.0 Security Fundamentals$$::text, 15.0, 'f64d419512815df7', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd0ce6aa-601f-5ac8-9cae-271cdbc72b7a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$A user cannot reach a web server. A standard ACL is applied inbound on the router closest to the server and permits only the user's subnet. What is the expected result?$$::text, $$[{"id": "A", "text": "If all higher-priority attributes are equal, the path with the shorter AS_PATH is selected.", "is_correct": false}, {"id": "B", "text": "Traffic from the server back to the user is blocked because standard ACLs do not filter return traffic based on destination.", "is_correct": true}, {"id": "C", "text": "The second interface may display an IP overlap error depending on IOS version.", "is_correct": false}, {"id": "D", "text": "Telnet sessions are blocked by the ACL.", "is_correct": false}]$$::jsonb, $$Given A user cannot reach a web server. and A standard ACL is applied inbound on the router closest to the server and permits only the user's subnet., the result is: Traffic from the server back to the user is blocked because standard ACLs do not filter return traffic based on destination.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$5.0 Security Fundamentals$$::text, 15.0, '73907681ace3821e', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f3471131-1ef7-565b-a5b4-76cf23dab34b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$A network uses WPA2-Enterprise with 802.1X. The RADIUS server becomes unreachable. What is the expected result?$$::text, $$[{"id": "A", "text": "NAT translation does not occur because the outside interface is not marked.", "is_correct": false}, {"id": "B", "text": "If all higher-priority attributes are equal, the path with the shorter AS_PATH is selected.", "is_correct": false}, {"id": "C", "text": "The switch floods the frame out all ports in the same VLAN except the ingress port.", "is_correct": false}, {"id": "D", "text": "New authentications fail; previously authenticated sessions may remain depending on configuration.", "is_correct": true}]$$::jsonb, $$Given A network uses WPA2-Enterprise with 802.1X. and The RADIUS server becomes unreachable., the result is: New authentications fail; previously authenticated sessions may remain depending on configuration.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$5.0 Security Fundamentals$$::text, 15.0, '167943e805d46a5f', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1541ea8a-cc2b-5263-b5a9-66d15c99513f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$An EIGRP router receives two paths to a destination with equal feasible distances. Both paths are feasible successors. What is the expected result?$$::text, $$[{"id": "A", "text": "The client resolves the name to an IPv4 address.", "is_correct": false}, {"id": "B", "text": "The host uses APIPA and cannot communicate outside the local segment.", "is_correct": false}, {"id": "C", "text": "The router performs equal-cost load balancing across both paths.", "is_correct": true}, {"id": "D", "text": "If all higher-priority attributes are equal, the path with the shorter AS_PATH is selected.", "is_correct": false}]$$::jsonb, $$Given An EIGRP router receives two paths to a destination with equal feasible distances. and Both paths are feasible successors., the result is: The router performs equal-cost load balancing across both paths.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$3.0 IP Connectivity$$::text, 25.0, '8e2b07fe9cdc80a5', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d0447db8-b447-5684-be9c-0b28c02cca80', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$A router receives the same route from OSPF (AD 110) and EIGRP internal (AD 90). Both routes have the same prefix length. What is the expected result?$$::text, $$[{"id": "A", "text": "Untagged traffic may leak between the two native VLANs.", "is_correct": false}, {"id": "B", "text": "The port is placed into err-disabled state.", "is_correct": false}, {"id": "C", "text": "The route with MED 50 is preferred because lower MED is preferred.", "is_correct": false}, {"id": "D", "text": "The EIGRP route is installed because it has the lower administrative distance.", "is_correct": true}]$$::jsonb, $$Given A router receives the same route from OSPF (AD 110) and EIGRP internal (AD 90). and Both routes have the same prefix length., the result is: The EIGRP route is installed because it has the lower administrative distance.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$3.0 IP Connectivity$$::text, 25.0, '2b4e57dfa52137b2', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('523fa097-301f-55f0-831a-24733ea30540', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$A network uses 802.1X port-based authentication. A non-802.1X device connects to a port in auto mode without a supplicant. What is the expected result?$$::text, $$[{"id": "A", "text": "The port remains in unauthorized state and blocks data traffic.", "is_correct": true}, {"id": "B", "text": "The router translates 192.168.1.10 to a public address before forwarding.", "is_correct": false}, {"id": "C", "text": "The server returns HTTP 201 Created.", "is_correct": false}, {"id": "D", "text": "The switch forwards the frame only out the destination port.", "is_correct": false}]$$::jsonb, $$Given A network uses 802.1X port-based authentication. and A non-802.1X device connects to a port in auto mode without a supplicant., the result is: The port remains in unauthorized state and blocks data traffic.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$5.0 Security Fundamentals$$::text, 15.0, '5f1b5cdaf5d9ea69', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0de9e461-c7c3-56ba-aadd-5ad8b40f8e35', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$A host is configured with a /27 subnet mask on a /24 network. Other hosts use /24. What is the expected result?$$::text, $$[{"id": "A", "text": "The switch dynamically learns and saves the MAC as a secure address.", "is_correct": false}, {"id": "B", "text": "The router uses both paths for traffic to that destination.", "is_correct": false}, {"id": "C", "text": "The host may not communicate with hosts outside its /27 unless the router has correct routes.", "is_correct": true}, {"id": "D", "text": "The switch forwards the frame only out the destination port.", "is_correct": false}]$$::jsonb, $$Given A host is configured with a /27 subnet mask on a /24 network. and Other hosts use /24., the result is: The host may not communicate with hosts outside its /27 unless the router has correct routes.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$1.0 Network Fundamentals$$::text, 20.0, '0dc6ef233f994fff', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13f48472-17dd-5f17-b5ab-75850518bb9c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$A router interface is configured with 'ip nat inside' and 'ip nat outside'. A packet from the inside network has a source of 192.168.1.10 and destination 8.8.8.8. What is the expected result?$$::text, $$[{"id": "A", "text": "The router translates 192.168.1.10 to a public address before forwarding.", "is_correct": true}, {"id": "B", "text": "The BDR takes over as the new DR and a new BDR is elected.", "is_correct": false}, {"id": "C", "text": "The server returns HTTP 201 Created.", "is_correct": false}, {"id": "D", "text": "The router performs equal-cost load balancing across both paths.", "is_correct": false}]$$::jsonb, $$Given A router interface is configured with 'ip nat inside' and 'ip nat outside'. and A packet from the inside network has a source of 192.168.1.10 and destination 8.8.8.8., the result is: The router translates 192.168.1.10 to a public address before forwarding.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$4.0 IP Services$$::text, 10.0, '8bec768057142c6f', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aab07b58-47ca-5ea2-bae5-f1103e7ddd30', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$Two switches are connected with an 802.1Q trunk. The native VLAN is mismatched between the two switches. What is the expected result?$$::text, $$[{"id": "A", "text": "Untagged traffic may leak between the two native VLANs.", "is_correct": true}, {"id": "B", "text": "Traffic to the gateway is redirected through the attacker (ARP spoofing/MITM).", "is_correct": false}, {"id": "C", "text": "The OSPF route is preferred; the static route appears only if OSPF route disappears.", "is_correct": false}, {"id": "D", "text": "The route with MED 50 is preferred because lower MED is preferred.", "is_correct": false}]$$::jsonb, $$Given Two switches are connected with an 802.1Q trunk. and The native VLAN is mismatched between the two switches., the result is: Untagged traffic may leak between the two native VLANs.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$2.0 Network Access$$::text, 20.0, 'b689aa790d1bf0ec', true) ON CONFLICT (id) DO NOTHING;
