INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('854c3f1f-7952-51ab-894e-c8b4b7013420', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$A REST API client sends DELETE /api/devices/1. The device exists and the client is authorized. What is the expected result?$$::text, $$[{"id": "A", "text": "The router acts as an NTP server with stratum 3.", "is_correct": false}, {"id": "B", "text": "Traffic to the gateway is redirected through the attacker (ARP spoofing/MITM).", "is_correct": false}, {"id": "C", "text": "The switch may flood traffic out all ports, enabling sniffing.", "is_correct": false}, {"id": "D", "text": "The server returns HTTP 204 No Content on success.", "is_correct": true}]$$::jsonb, $$Given A REST API client sends DELETE /api/devices/1. and The device exists and the client is authorized., the result is: The server returns HTTP 204 No Content on success.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$6.0 Automation and Programmability$$::text, 10.0, '5d1ec973f9ffd705', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fbc5533c-d38c-595c-91d2-b0e459d20e6d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$A host sends a DHCP Discover message. The DHCP server is on a different subnet and no relay agent is configured. What is the expected result?$$::text, $$[{"id": "A", "text": "The host does not receive an IP address because broadcasts are not forwarded across subnets.", "is_correct": true}, {"id": "B", "text": "BPDU Guard may place the port into err-disabled state.", "is_correct": false}, {"id": "C", "text": "A temporary Layer 2 loop may form until STP converges; BPDU Guard can prevent it.", "is_correct": false}, {"id": "D", "text": "The switch dynamically learns and saves the MAC as a secure address.", "is_correct": false}]$$::jsonb, $$Given A host sends a DHCP Discover message. and The DHCP server is on a different subnet and no relay agent is configured., the result is: The host does not receive an IP address because broadcasts are not forwarded across subnets.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$4.0 IP Services$$::text, 10.0, 'b034950b8ad0efed', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c7d95a0e-5c91-5811-ad27-b1a9979157a0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$A switch receives a broadcast frame on port Gi0/1. The switch has learned the source MAC on Gi0/1. What is the expected result?$$::text, $$[{"id": "A", "text": "The switch floods the frame out all ports in the same VLAN except Gi0/1.", "is_correct": true}, {"id": "B", "text": "The client may not be able to connect unless backward compatibility is enabled.", "is_correct": false}, {"id": "C", "text": "The host does not receive an IP address because broadcasts are not forwarded across subnets.", "is_correct": false}, {"id": "D", "text": "The second interface may display an IP overlap error depending on IOS version.", "is_correct": false}]$$::jsonb, $$Given A switch receives a broadcast frame on port Gi0/1. and The switch has learned the source MAC on Gi0/1., the result is: The switch floods the frame out all ports in the same VLAN except Gi0/1.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$2.0 Network Access$$::text, 20.0, 'c5c0dbeb4d9ec47b', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43b549c0-fb81-5173-be14-6ed01eebb05e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$A network administrator enables 'ntp master 3' on a router. Other routers are configured with 'ntp server' pointing to it. What is the expected result?$$::text, $$[{"id": "A", "text": "The router uses both paths for traffic to that destination.", "is_correct": false}, {"id": "B", "text": "BPDU Guard may place the port into err-disabled state.", "is_correct": false}, {"id": "C", "text": "The switch may flood traffic out all ports, enabling sniffing.", "is_correct": false}, {"id": "D", "text": "The router acts as an NTP server with stratum 3.", "is_correct": true}]$$::jsonb, $$Given A network administrator enables 'ntp master 3' on a router. and Other routers are configured with 'ntp server' pointing to it., the result is: The router acts as an NTP server with stratum 3.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$4.0 IP Services$$::text, 10.0, 'f8c2bd7f8d3c866c', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81b410dd-5f59-5bfc-8ecc-ce8ccb06a8fc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$An engineer configures two interfaces with the same IP address on a router. The network masks are different. What is the expected result?$$::text, $$[{"id": "A", "text": "Traffic to the gateway is redirected through the attacker (ARP spoofing/MITM).", "is_correct": false}, {"id": "B", "text": "Excess traffic is queued and may be dropped if the queue overflows.", "is_correct": false}, {"id": "C", "text": "The host may not communicate with hosts outside its /27 unless the router has correct routes.", "is_correct": false}, {"id": "D", "text": "The second interface may display an IP overlap error depending on IOS version.", "is_correct": true}]$$::jsonb, $$Given An engineer configures two interfaces with the same IP address on a router. and The network masks are different., the result is: The second interface may display an IP overlap error depending on IOS version.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$1.0 Network Fundamentals$$::text, 20.0, '96aad8e6ba17ebdf', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6e8924c4-af59-55b1-980b-066b8ecc9d0e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$A router has OSPF enabled on an interface with no neighbors listed. The interface is administratively shut down. What is the expected result?$$::text, $$[{"id": "A", "text": "The switch may flood traffic out all ports, enabling sniffing.", "is_correct": false}, {"id": "B", "text": "The server returns HTTP 201 Created.", "is_correct": false}, {"id": "C", "text": "The local port negotiates to trunking if in dynamic desirable or auto mode.", "is_correct": false}, {"id": "D", "text": "OSPF will not form adjacencies until the interface is no shutdown.", "is_correct": true}]$$::jsonb, $$Given A router has OSPF enabled on an interface with no neighbors listed. and The interface is administratively shut down., the result is: OSPF will not form adjacencies until the interface is no shutdown.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$3.0 IP Connectivity$$::text, 25.0, 'e3a0858a05750f9f', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
