INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('835c10c0-a1a6-5789-b3e8-499f3fcc77c0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'simlet', 4, 'analyze', $$Which neighbor is an iBGP peer?

Router# show ip bgp summary
BGP router identifier 192.168.1.1, local AS number 65001
Neighbor        V    AS MsgRcvd MsgSent   TblVer  InQ OutQ Up/Down  State/PfxRcd
10.1.1.1        4 65002     120     125        5    0    0 01:23:45        150
10.1.1.5        4 65001     110     115        5    0    0 02:10:12        200$$::text, $$[{"id": "A", "text": "10.1.1.1 in AS 65002", "is_correct": false}, {"id": "B", "text": "10.1.1.5 in AS 65001", "is_correct": true}, {"id": "C", "text": "Both are iBGP peers", "is_correct": false}, {"id": "D", "text": "Neither is an iBGP peer", "is_correct": false}]$$::jsonb, $$An iBGP peer has the same AS number as the local router. 10.1.1.5 is in AS 65001, matching the local AS.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$3.0 IP Connectivity$$::text, 25.0, 'fc00f87edfb44598', true) ON CONFLICT (id) DO NOTHING;
