INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('03a036c4-7e6b-5853-a26d-968eced695d8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'simlet', 4, 'analyze', $$Which path is selected for 192.168.0.0?

Router# show ip bgp
Network          Next Hop            Metric LocPrf Weight Path
*> 192.168.0.0     10.1.1.1               0             0 65002 i
*                   10.1.1.5               0             0 65003 i$$::text, $$[{"id": "A", "text": "Path via 10.1.1.5 because it has lower metric", "is_correct": false}, {"id": "B", "text": "Path via 10.1.1.1 because it has the best weight", "is_correct": true}, {"id": "C", "text": "Both paths are used for load balancing", "is_correct": false}, {"id": "D", "text": "Neither; the route is not installed", "is_correct": false}]$$::jsonb, $$Weight is the first attribute in BGP path selection; the path via 10.1.1.1 has weight 0 while the other also has 0, but the '>' indicates the selected path.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$3.0 IP Connectivity$$::text, 25.0, '6f096ca8db36bb59', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd0e43e5-d5e7-5eb1-ab2f-7a586a04827a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'simlet', 4, 'analyze', $$How many addresses remain available in the pool?

Router# show ip dhcp pool
Pool MYPOOL :
 Utilization mark (high/low)    : 100 / 0
 Subnet size (first/next)       : 0 / 0
 Total addresses                : 254
 Leased addresses               : 200
 Excluded addresses             : 2
 Pending event                  : none$$::text, $$[{"id": "A", "text": "254", "is_correct": false}, {"id": "B", "text": "200", "is_correct": false}, {"id": "C", "text": "52", "is_correct": true}, {"id": "D", "text": "256", "is_correct": false}]$$::jsonb, $$254 total - 200 leased - 2 excluded = 52 available.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$4.0 IP Services$$::text, 10.0, 'cf85f5228d4bbe91', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

