INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('702cc87a-c525-55bb-bf5d-62413bbf82b1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'simlet', 4, 'analyze', $$Which QoS treatment is applied to voice traffic?

Router# show policy-map interface gi0/0
