INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2cce8747-77c5-5076-ab0e-64a1152a3b9d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'simlet', 4, 'analyze', $$What is the native VLAN on interface Gi0/1?

Switch# show interfaces trunk
Port        Mode             Encapsulation  Status        Native vlan
