INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('51b16562-d5d6-5754-aaff-13824b1b5880', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'simlet', 4, 'analyze', $$What is the feasible distance to 10.0.0.0/24?

